from typing import List

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        total = n * n
        freq = [0] * (total + 1)

        for row in grid:
            for num in row:
                freq[num] += 1

        a = b = -1
        for i in range(1, total + 1):
            if freq[i] == 2:
                a = i
            elif freq[i] == 0:
                b = i

        return [a, b]
